# New Database and Git questions. code/output come from sql_out.json / git_out.json (real runs).
# after = file anchor; topic_after / topic_before = where the title goes in the topics file.
DB = [
  dict(q='How do you create and change a table with CREATE TABLE and ALTER TABLE?', level='Basics',
       after='What is the difference between DDL, DML, DCL and TCL?', topic_after='What is the difference between DDL, DML, DCL and TCL?',
       a="CREATE TABLE defines the table with its columns, types and constraints. ALTER TABLE changes it later: adding a column, renaming a column or renaming the table, and most databases can also drop columns or change types. In real projects I never run ALTER by hand on production; I put every change in a migration file (Alembic, Flyway or Prisma) so all environments stay in sync."),
  dict(q='What is the difference between a primary key and a unique key?', level='Basics',
       after='What is a primary key?', topic_after='What is a primary key?',
       a="Both stop duplicate values, but a table has only one primary key and it can never be NULL, while I can have many UNIQUE constraints and they allow NULLs (in most databases, several of them). The primary key is the row's identity that foreign keys point to; a unique key is a business rule, like one account per email. Here the second NULL email is fine, but the duplicate email is rejected."),
  dict(q='What are candidate, composite, surrogate and natural keys?', level='Intermediate',
       after='What is the difference between a primary key and a unique key?', topic_after='What is the difference between a primary key and a unique key?',
       a="A candidate key is any column, or set of columns, that could uniquely identify a row, and the one I pick becomes the primary key. A composite key uses more than one column, like (student_id, course_id) in a join table. A natural key comes from real data, like an email, while a surrogate key is an artificial id with no meaning; I usually use a surrogate id as the primary key and keep the natural key UNIQUE, because real-world values like emails can change."),
  dict(q='How do you paginate results with LIMIT and OFFSET?', level='Basics',
       after='How do WHERE, ORDER BY and LIMIT work in a SELECT?', topic_after='How do WHERE, ORDER BY and LIMIT work in a SELECT?',
       a="LIMIT sets how many rows to return and OFFSET how many to skip first, so page n is OFFSET (n - 1) * page_size. I always add ORDER BY, because without it the database can return rows in any order and pages may repeat or miss rows. For deep pages OFFSET gets slow because the skipped rows are still read, so on big tables I use keyset pagination: WHERE id > last_seen_id ORDER BY id LIMIT 20."),
  dict(q='What do COALESCE, IFNULL and NULLIF do?', level='Basics',
       after='How do you handle NULL values in SQL?', topic_after='How do you handle NULL values in SQL?',
       a="COALESCE returns the first non-NULL value from its list, and IFNULL (ISNULL in SQL Server) is the two-argument version. NULLIF does the opposite: it returns NULL when both values are equal, which turns empty strings or zeros into NULL. My favorite trick is total / NULLIF(count, 0), which gives NULL instead of a divide-by-zero error."),
  dict(q='How do you convert data types with CAST?', level='Basics',
       after='What do COALESCE, IFNULL and NULLIF do?', topic_after='What do COALESCE, IFNULL and NULLIF do?',
       a="CAST(value AS type) converts a value to another type, like text to a number or a number to text. The classic trap is integer division: 7 / 2 gives 3, so I cast one side to REAL or DECIMAL to get 3.5. Casting a decimal to an integer just cuts off the fraction, so I use ROUND first if I want proper rounding."),
  dict(q='Which math functions do you use in SQL (ROUND, ABS, CEIL, FLOOR, MOD)?', level='Basics',
       after='Which string functions do you use most in SQL?', topic_after='Which string functions do you use most in SQL?',
       a="ROUND(x, 2) rounds to 2 decimal places, ABS removes the sign, CEIL rounds up and FLOOR rounds down, and % (or MOD() in other databases) gives the remainder. I use CEIL for page counts, like CEIL(total / 10.0), and % 2 to find even or odd ids. In SQLite CEIL and FLOOR return a REAL, so I cast them to INTEGER when I need a whole number."),
  dict(q='What is the difference between INTERSECT and EXCEPT?', level='Intermediate',
       after='What is the difference between UNION and UNION ALL?', topic_after='What is the difference between UNION and UNION ALL?',
       a="INTERSECT returns only the rows that appear in both queries, and EXCEPT returns the rows from the first query that are not in the second (Oracle calls it MINUS). Like UNION, both remove duplicates and need the same number of columns. I use EXCEPT for quick data checks, like finding customers who exist in one system but not the other."),
  dict(q='What do ANY and ALL do with a subquery?', level='Intermediate',
       after='What does EXISTS do?', topic_after='What does EXISTS do?',
       a="salary > ALL (subquery) is true when the value beats every row the subquery returns, and salary > ANY (subquery) when it beats at least one; = ANY is the same as IN. SQLite doesn't support ANY and ALL, so here I use the rewrite that works everywhere: > ALL is > MAX(...) and > ANY is > MIN(...). I often prefer the MAX/MIN form anyway because it reads more clearly in code reviews."),
  dict(q='What do FIRST_VALUE and LAST_VALUE do?', level='Intermediate',
       after='How do you use LAG and LEAD?', topic_after='How do you use LAG and LEAD?',
       a="FIRST_VALUE returns the value from the first row of the window and LAST_VALUE from the last row, so I can show the top earner of each department on every row. The trap is LAST_VALUE: the default frame stops at the current row, so it just returns the current row's value. I add ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING, or flip the ORDER BY and use FIRST_VALUE instead."),
  dict(q='What is the difference between GROUP BY and a window function like SUM() OVER?', level='Intermediate',
       after='What are window functions? Explain ROW_NUMBER, RANK and DENSE_RANK.', topic_before='What are window functions? Explain ROW_NUMBER, RANK and DENSE_RANK.',
       a="GROUP BY collapses each group into one row, so I lose the detail rows. A window function like SUM(amount) OVER (PARTITION BY region) computes the same total but keeps every row and adds the total as a new column. I use it when I need detail and totals together, like each sale's share of its region's total, without a self-join."),
  dict(q='What is the difference between a clustered and a non-clustered index?', level='Intermediate',
       after='Does column order matter in a composite index?', topic_after='Does column order matter in a composite index?',
       a="A clustered index decides the physical order of the rows, so the table itself is the index and there can only be one; in SQL Server and MySQL InnoDB it's usually the primary key. A non-clustered index is a separate structure that stores the key plus a pointer to the row, so a lookup searches the index and then jumps to the row. In SQLite the rowid table works like the clustered index, and every CREATE INDEX is non-clustered, as the query plan shows."),
  dict(q='What is an ER diagram, and what are one-to-one, one-to-many and many-to-many relationships?', level='Basics',
       after='What is denormalization and when would you use it?', topic_before='How would you design a database for a simple shop (users, products, orders)?',
       a="An ER (entity-relationship) diagram shows the tables as boxes and draws the relationships between them, and I sketch one before writing any CREATE TABLE. One-to-one is a foreign key with a UNIQUE constraint, like user and profile; one-to-many puts the foreign key on the 'many' side, like orders.user_id. Many-to-many, like students and courses, needs a junction table holding both foreign keys."),
]

GIT = [
  dict(q='What does git commit -a do?', level='Basics',
       after='What do git add, git commit and git status do?', topic_after='What do git add, git commit and git status do?',
       a="git commit -a stages every change to files Git already tracks and commits them in one step, so I can skip git add. It does not pick up new, untracked files, which is why notes.txt is still untracked here. I use git commit -am for quick fixes, but git add -p when I want to review exactly what goes in."),
  dict(q='How do you search code with git grep?', level='Intermediate',
       after='How do you search the commit history?', topic_after='How do you search the commit history?',
       a="git grep searches the text of the files Git tracks, so it skips node_modules and other ignored folders and is very fast. -n adds line numbers and -c counts matches per file. I can also pass a tag or commit to search an old version without checking it out."),
  dict(q='What does git push -u (set upstream) do?', level='Basics',
       after='What do git push, git pull and git fetch do?', topic_after='What do git push, git pull and git fetch do?',
       a="git push -u origin feature pushes the branch and also sets origin/feature as its upstream, the branch it tracks. After that a plain git push or git pull knows where to go, and git status shows how far ahead or behind I am. I use -u the first time I push a new branch, and git branch -vv shows what each branch tracks."),
  dict(q='What do git shortlog and git describe do?', level='Intermediate',
       after='What does a release workflow with tags look like?', topic_after='What does a release workflow with tags look like?',
       a="git shortlog groups commits by author, which I use for release notes, and git shortlog -sn gives a quick count of commits per person. git describe names the current commit from the nearest annotated tag: v1.0-3-g3ab421d means 3 commits after v1.0, at commit 3ab421d. I put the git describe output into build version strings so I can always tell which commit a build came from."),
  dict(q='What does git archive do?', level='Intermediate',
       after='What do git shortlog and git describe do?', topic_after='What do git shortlog and git describe do?',
       a="git archive exports a snapshot of a commit or tag as a tar or zip file, with only the tracked files and no .git folder. Ignored files like node_modules are left out automatically, so it's a clean way to ship source code. I add --prefix=app/ so everything unpacks into one folder."),
]
